import json
from fractions import Fraction

def multiply(a, b):
    result = [Fraction(0)] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            result[i + j] += x * y
    return result

def divide_exact(numerator, denominator):
    remainder = numerator[:]
    quotient = [Fraction(0)] * (len(numerator) - len(denominator) + 1)
    while remainder and remainder[-1] == 0:
        remainder.pop()
    while len(remainder) >= len(denominator):
        degree = len(remainder) - len(denominator)
        coefficient = remainder[-1] / denominator[-1]
        quotient[degree] += coefficient
        for j, value in enumerate(denominator):
            remainder[degree + j] -= coefficient * value
        while remainder and remainder[-1] == 0:
            remainder.pop()
    if remainder:
        raise ArithmeticError("Nonzero remainder")
    return quotient

try:
    # u = cos(x), cot(x/2) = (1+u)/sin(x).
    # Reversing bounds gives integral_0^1 (1+u)(1-u^4)/(1-u^2) du.
    # The cancellation is valid for 0 <= u < 1; its polynomial
    # continuation at u = 1 settles the original improper endpoint.
    numerator = multiply(
        [Fraction(1), Fraction(1)],
        [Fraction(1), Fraction(0), Fraction(0), Fraction(0), Fraction(-1)]
    )
    denominator = [Fraction(1), Fraction(0), Fraction(-1)]
    polynomial = divide_exact(numerator, denominator)
    terms = [coefficient / (degree + 1)
             for degree, coefficient in enumerate(polynomial)]
    answer = sum(terms, Fraction(0))
    print(json.dumps({
        "final_answer": str(answer),
        "evidence": {
            "substitution": "u=cos(x); bounds reversed to [0,1]",
            "transformed_integrand": "(1+u)(1-u^4)/(1-u^2)",
            "polynomial_coefficients_ascending": list(map(str, polynomial)),
            "integrated_terms": list(map(str, terms)),
            "endpoint": "removable singularity; polynomial continuation"
        }
    }, separators=(",", ":")))
except ArithmeticError:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": "Exact division failed"}))
